contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function driving the test
    // depositAmount: amount to deposit into c from this contract
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient balance to send");

        // Record contract balances before any action
        uint beforeTesterBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        // Make a deposit into C from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Balances immediately after deposit
        uint afterDepositTesterBal = address(this).balance;
        uint afterDepositCbal = address(c).balance;

        // The deposit must move exactly depositAmount from tester to c
        // (if deposit did not behave this way the later invariant will fail)
        // Now attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Balances after withdraw attempt
        uint finalTesterBal = address(this).balance;
        uint finalCbal = address(c).balance;

        // General rule:
        // - The deposit reduced this contract's balance by depositAmount and increased c's balance by depositAmount.
        // - If withdrawAll succeeded then this contract's balance increased by depositAmount compared to afterDepositTesterBal
        //   and c's balance decreased by depositAmount compared to afterDepositCbal.
        // - If withdrawAll reverted then neither party's balance changed due to withdrawAll (final balances equal after-deposit balances).
        assert(
            // deposit effect (must hold regardless)
            (afterDepositTesterBal + depositAmount == beforeTesterBal) && (afterDepositCbal == beforeCbal + depositAmount)
            &&
            (
                // case: withdrawAll succeeded
                (!reverted && finalTesterBal == afterDepositTesterBal + depositAmount && finalCbal + depositAmount == afterDepositCbal)
                ||
                // case: withdrawAll reverted
                (reverted && finalTesterBal == afterDepositTesterBal && finalCbal == afterDepositCbal)
            )
        );
    }

    // Allow receiving Ether when withdrawAll sends funds
    receive() external payable {}
}

