// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint beforeTesterBal = address(this).balance;
        uint beforeCbal = address(c).balance;
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint afterDepositTesterBal = address(this).balance;
        uint afterDepositCbal = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint finalTesterBal = address(this).balance;
        uint finalCbal = address(c).balance;
        assertTrue((afterDepositTesterBal + depositAmount == beforeTesterBal) && (afterDepositCbal == beforeCbal + depositAmount)
            &&
            (
                // case: withdrawAll succeeded
                (!reverted && finalTesterBal == afterDepositTesterBal + depositAmount && finalCbal + depositAmount == afterDepositCbal)
                ||
                // case: withdrawAll reverted
                (reverted && finalTesterBal == afterDepositTesterBal && finalCbal == afterDepositCbal)
            ));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
